13	@Entity
14	@Getter
15	@NoArgsConstructor
16	@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
17	@DiscriminatorColumn(name = "payment_type")
18	public abstract class Payment extends BaseTimeEntity {
19	
20	    @Id
21	    @GeneratedValue(strategy = GenerationType.IDENTITY)
22	    private Long id;
23	
24	    @OneToOne(fetch = FetchType.LAZY)
25	    @JoinColumn(name = "order_id")
26	    private Order order;
27	
28	    @OneToOne(fetch = FetchType.LAZY)
29	    @JoinColumn(name = "sale_id")
30	    private Sale sale; // 판매와 연결
31	
32	    @ManyToOne(fetch = FetchType.LAZY)
33	    @JoinColumn(name = "user_id", nullable = false)
34	    private User user;
35	
36	    @Column(nullable = false)
37	    private double paidAmount; // 결제 금액
38	    @Column(nullable = false)
39	    private boolean isSuccess = false; // 기본값 false
40	
41	    private LocalDateTime paymentDate; // 결제 완료 시간
42	
43	    @Enumerated(EnumType.STRING)
44	    private PaymentStatus status = PaymentStatus.PENDING; // 기본값 PENDING
45	
46	
47	    public void assignOrder(Order order) {
48	        this.order = order;
49	        this.sale = null; // 서로 배타적 관계
50	    }
51	
52	    public void assignSale(Sale sale) {
53	        this.sale = sale;
54	        this.order = null; // 서로 배타적 관계
55	    }
56	    public void assignUser(User user) {
57	        this.user = user;
58	    }
59	
60	    public void setPaidAmount(double paidAmount) {
61	        this.paidAmount = paidAmount;
62	        this.isSuccess = paidAmount > 0; // 결제 금액이 양수면 성공으로 간주
63	    }
64	    public void updateSuccessStatus(boolean success) {
65	        this.isSuccess = success;
66	        if (success) {
67	            this.paymentDate = LocalDateTime.now(); // 성공 시 결제 완료 시간 갱신
68	        }
69	    }
70	    public void updateStatus(PaymentStatus newStatus) {
71	        if (this.status.canTransitionTo(newStatus)) {
72	            this.status = newStatus;
73	        } else {
74	            throw new IllegalStateException("결제 상태 전환이 허용되지 않습니다: " + this.status + " -> " + newStatus);
75	        }
76	    }
