79	}
 1	package com.fream.back.domain.payment.entity;
 2	
 3	public enum PaymentStatus {
 4	    PENDING, // 결제 대기
 5	    PAID, // 결제 완료
 6	    REFUND_REQUESTED, // 환불 대기
 7	    REFUNDED, // 환불 완료
 8	    FAILED;
 9	
10	    public boolean canTransitionTo(PaymentStatus newStatus) {
11	        switch (this) {
12	            case PENDING:
13	                return newStatus == PAID;
14	            case PAID:
15	                return newStatus == REFUND_REQUESTED || newStatus == REFUNDED;
16	            case REFUND_REQUESTED:
17	                return newStatus == REFUNDED;
18	            default:
19	                return false;
20	        }
21	    }
22	}

